import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        int m = n;
        int qavat = 0;
        while (m > 1) {
            m = (m + 1) / 2;
            qavat++;
        }
        System.out.println((2 * n - 1) + " " + (qavat + 1));
    }
}

